package gg.eternal.core.hud;
import gg.eternal.core.EternalCore; import gg.eternal.core.config.CoreConfig; import gg.eternal.core.state.InputState; import net.minecraft.client.Minecraft; import net.minecraft.client.gui.GuiGraphics;
public final class HudRenderer { private static final String[] MODULES={"FPS","CPS","Keystrokes","Coordinates","Ping","Speed","Direction","Memory","Session"}; private static final int TEXT=0xFFF4F5F7,ACCENT=0xFFFF4242; private HudRenderer(){} public static void install(){} public static String[] modules(){return MODULES;} public static void render(GuiGraphics g){Minecraft mc=Minecraft.getInstance();if(mc.options.hideGui||mc.player==null||mc.screen!=null)return;int fallbackY=10;for(String name:MODULES){if(!CoreConfig.INSTANCE.on(name))continue;int[] pos=CoreConfig.INSTANCE.pos(name,10,fallbackY);String text=value(name);int width=mc.font.width(text)+12;g.fill(pos[0],pos[1],pos[0]+width,pos[1]+17,0xB80A0B0D);g.fill(pos[0],pos[1],pos[0]+2,pos[1]+17,ACCENT);g.drawString(mc.font,text,pos[0]+7,pos[1]+5,TEXT,true);fallbackY+=21;}} public static String value(String n){Minecraft mc=Minecraft.getInstance();if(n.equals("FPS"))return "FPS "+mc.getFps();if(n.equals("CPS"))return "CPS "+InputState.leftCps()+" | "+InputState.rightCps();if(n.equals("Keystrokes"))return keys();if(mc.player==null)return n+" --";return switch(n){case "Coordinates"->String.format("XYZ %.0f / %.0f / %.0f",mc.player.getX(),mc.player.getY(),mc.player.getZ());case "Ping"->"PING "+(mc.getConnection()!=null&&mc.getConnection().getPlayerInfo(mc.player.getUUID())!=null?mc.getConnection().getPlayerInfo(mc.player.getUUID()).getLatency():0)+"ms";case "Speed"->String.format("SPEED %.2f",Math.sqrt(mc.player.getDeltaMovement().x*mc.player.getDeltaMovement().x+mc.player.getDeltaMovement().z*mc.player.getDeltaMovement().z)*20.0);case "Direction"->"DIR "+Math.round(mc.player.getYRot())+"°";case "Memory"->{Runtime r=Runtime.getRuntime();yield "MEM "+((r.totalMemory()-r.freeMemory())/1048576)+" / "+(r.maxMemory()/1048576)+" MB";}case "Session"->"SESSION "+format(EternalCore.sessionMillis());default->n;};} private static String keys(){return (InputState.keyDown(87)?"[W]":" W ")+" "+(InputState.keyDown(65)?"[A]":" A ")+" "+(InputState.keyDown(83)?"[S]":" S ")+" "+(InputState.keyDown(68)?"[D]":" D ");} private static String format(long ms){long s=ms/1000;return String.format("%02d:%02d:%02d",s/3600,(s/60)%60,s%60);} }
